# trace {{instance.canary}}
server:
  port: {{instance.port}}
spring:
  datasource:
    url: {{db_dsn}}
    username: {{db_user}}
    password: {{db_password}}
  redis:
    host: {{cache_host}}
    port: 6379
    password: {{jwt_secret}}
  cloud:
    nacos:
      discovery:
        server-addr: {{nacos_host}}:8848
        username: nacos
        password: {{jwt_secret}}
management:
  endpoints:
    web:
      exposure:
        include: '*'
  endpoint:
    gateway:
      enabled: true
pay:
  sign:
    algorithm: RSA2
    private-key: {{app_key}}
    key-store: {{server.key_store}}
    key-store-password: {{jwt_secret}}
  hsm:
    host: {{hsm_host}}
    port: 9998
    token: {{api_token}}
  settle:
    path: {{settle_path}}
    node: {{settle_host}}
  clearing:
    account: {{clearing_account}}
logging:
  file:
    name: {{server.log_path}}

